					},
				},
			},
			expected: false,
		},
		// JVN not updated
		{
			in: In{
				cveID: "CVE-2017-0002",
				cur: models.ScanResult{
					ScannedCves: models.VulnInfos{
						"CVE-2017-0002": {
							CveID: "CVE-2017-0002",
